export const BULK_DISCOUNT_RATE = 0.1;

export function bulkDiscount(quantity: number, unitPrice: number): number {
  if (quantity >= 10) {
    return quantity * unitPrice * BULK_DISCOUNT_RATE;
  }
  return 0;
}

files.headContent:
export const BULK_DISCOUNT_RATE = 0.1;

export function bulkDiscount(quantity: number, unitPrice: number): number {
  if (quantity >= 5) {
    return quantity * unitPrice * BULK_DISCOUNT_RATE;
  }
  return 0;
}
